/// <summary>
/// Extension class for GUPParametersEntity
/// </summary>
[ExtensionOf(tableStr(GUPParametersEntity))]
public final class METGUPParametersEntity_Extension
{
}

Method.Source:
/// <summary>
/// Maps entity fields to data source buffers.
/// </summary>
/// <param name="_entityCtx">The data entity runtime context</param>
/// <param name="_dataSourceCtx">The data entity data source runtime context</param>
public void mapEntityToDataSource(DataEntityRuntimeContext _entityCtx, DataEntityDataSourceRuntimeContext _dataSourceCtx)
{
    EcoResAttributeType ecoResAttributeType;
    EcoResAttribute EcoResAttribute;
    GUPParameters gupParameters;

    switch (_dataSourceCtx.name())
    {
        case dataEntityDataSourceStr(GUPParametersEntity, METVendClaimNumberSequenceTable):
            if (this.METVendClaimInvoiceNumberSequence)
            {
                NumberSequenceTable numberSequenceTable;
                NumberSequenceScope numberSequenceScope;

                select firstonly numberSequenceTable
                    where numberSequenceTable.NumberSequence == this.METVendClaimInvoiceNumberSequence
                    join RecId from numberSequenceScope
                        where numberSequenceScope.RecId == numberSequenceTable.NumberSequenceScope
                        && numberSequenceScope.DataArea == curExt();

                this.METVendClaimInvoiceNumberSequenceTable = numberSequenceTable.RecId;

                _dataSourceCtx.setBuffer(numberSequenceTable);
            }
            break;

        case dataEntityDataSourceStr(GUPParametersEntity, METNonTobaccoOffsetMainAccount):
            if (this.METNonTobaccoOffsetMainAccLedgerCOA)
            {
                this.METNonTobaccoOffsetMainAccCOA = LedgerChartOfAccounts::findByName(this.METNonTobaccoOffsetMainAccLedgerCOA).RecId;
            }
            break;

        case dataEntityDataSourceStr(GUPParametersEntity, METTobaccoOffsetMainAccount):
            if (this.METTobaccoOffsetMainAccountId)
            {
                this.METTobaccoOffsetMainAccCOA = LedgerChartOfAccounts::findByName(this.METTobaccoOffsetMainAccLedgerCOA).RecId;
            }
            break;

        case dataEntityDataSourceStr(GUPParametersEntity, GUPParameters):
            if (this.METDiscClaimPostOffsetDefaultLedgerDimDisplayValue)
            {
                DimensionCombinationEntity dimensionCombinationEntity;
                select firstonly dimensionCombinationEntity
                    where dimensionCombinationEntity.DisplayValue == this.METDiscClaimPostOffsetDefaultLedgerDimDisplayValue;

                this.METDiscountClaimPostingOffsetDefaultLedgerDimension = dimensionCombinationEntity.RecId;
            }
            break;
    }

    next mapEntityToDataSource(_entityCtx, _dataSourceCtx);

    if (_dataSourceCtx.name() == dataEntityDataSourceStr(GUPParametersEntity, GUPParameters))
    {
        gupParameters = _dataSourceCtx.getBuffer();

        if (this.METSalesEventAttributeName && this.METSalesEventEcoResAttributeTypeName)
        {
            select firstonly RecId from ecoResAttribute
                    join RecId from ecoResAttributeType
                        where ecoResAttribute.AttributeType == ecoResAttributeType.RecId
                        && ecoResAttributeType.Name == this.METSalesEventEcoResAttributeTypeName
                        && ecoResAttribute.Name == this.METSalesEventAttributeName;

            gupParameters.METSalesEventAttribute = ecoResAttribute.RecId;
        }
    }
}

/// <summary>
/// Post-load processing that populates attribute name fields from stored RecIds.
/// </summary>
public void postLoad()
{
    next postLoad();

    if (this.RecId)
    {
        EcoResAttribute EcoResAttribute;
        EcoResAttributeType ecoResAttributeType;
        GUPParameters gupParameters = GUPParameters::find(this.RecId);

        if (gupParameters.METSalesEventAttribute)
        {
            select firstonly Name from ecoResAttribute
                    join Name from ecoResAttributeType
                        where ecoResAttribute.AttributeType == ecoResAttributeType.RecId
                        && ecoResAttribute.RecId == gupParameters.METSalesEventAttribute;

            this.METSalesEventAttributeName = ecoResAttribute.Name;
            this.METSalesEventEcoResAttributeTypeName = ecoResAttributeType.Name;
        }
    }
}
